data.script:
let source = draft.content;
let error = '', promptCancelled = false;
if (source.includes('{{')) {
  const variables = Object.create(null), order = [];
  const expression = /{{([#^/]?)(?:(bool|date):)?([A-Za-z_][A-Za-z0-9_]*)(\?)?}}/g;
  let match;
  while ((match = expression.exec(source))) {
    const marker = match[1], kind = match[2] || 'text', key = match[3];
    if (marker === '/') continue;
    if (variables[key] && variables[key] !== kind) { error = 'A Mustache variable has conflicting types: ' + key; break; }
    if (!variables[key]) { variables[key] = kind; order.push(key); }
  }
  const unparsed = source.replace(expression, '');
  if (unparsed.includes('{{') || unparsed.includes('}}')) error = 'This Mustache expression is not supported.';
  if (!error && order.length) {
    const prompt = Prompt.create(); prompt.title = 'Fill template';
    for (const key of order) {
      if (variables[key] === 'bool') prompt.addSwitch(key, key, false);
      else if (variables[key] === 'date') prompt.addDatePicker(key, key, new Date(), {mode:'date'});
      else prompt.addTextField(key, key, '');
    }
    prompt.addButton('Continue');
    if (!prompt.show()) promptCancelled = true;
    else {
      const values = Object.create(null);
      for (const key of order) {
        const value = prompt.fieldValues[key];
        if (variables[key] === 'date') {
          if (!(value instanceof Date) || isNaN(value.getTime())) { error = 'Invalid date: ' + key; break; }
          const pad = n => String(n).padStart(2,'0');
          values[key] = value.getFullYear() + '-' + pad(value.getMonth()+1) + '-' + pad(value.getDate());
        } else if (typeof value !== (variables[key] === 'bool' ? 'boolean' : 'string')) { error = 'Invalid value: ' + key; break; }
        else values[key] = value;
      }
      if (!error) {
        source = source.replace(expression, (all, marker, kind, key) => '{{' + marker + key + '}}');
        source = MustacheTemplate.renderTemplate(source, values);
      }
    }
  }
}
source = draft.processTemplate(source).replace(/\r\n?/g, '\n');
const items = [], stack = [];
function fail(message) { if (!error) error = message; }
function parseTags(text) {
  const tags = {}; const title = text.replace(/(?:^|\s)@([A-Za-z]+)(?:\(([^()]*)\))?(?=\s|$)/g, (all, name, value) => {
    if (Object.prototype.hasOwnProperty.call(tags, name.toLowerCase())) { fail('Duplicate TaskPaper tag: ' + name); }
    tags[name.toLowerCase()] = value === undefined ? true : value.trim(); return ' ';
  }).trim();
  return {title, tags};
}
function metadata(tags, type) {
  const a = {}; const allowed = ['when','defer','due','deadline','done','completed','canceled','cancelled','tag','tags'];
  if (type === 'project') allowed.push('area','areaid');
  if (type === 'to-do') allowed.push('list','project','listid','heading');
  if (type === 'heading') allowed.push('archived');
  for (const k of Object.keys(tags)) if (!allowed.includes(k)) fail('Unsupported TaskPaper tag: @' + k);
  if (tags.when || tags.defer) a.when = tags.when || tags.defer;
  if (tags.due || tags.deadline) a.deadline = tags.due || tags.deadline;
  if (tags.done || tags.completed) a.completed = true;
  if (tags.canceled || tags.cancelled) a.canceled = true;
  if (tags.tag || tags.tags) a.tags = String(tags.tag || tags.tags).split(',').map(t => t.trim()).filter(Boolean);
  if (type === 'project') { if(tags.area) a.area=tags.area; if(tags.areaid) a['area-id']=tags.areaid; }
  if (type === 'to-do') { if(tags.list || tags.project) a.list=tags.list || tags.project; if(tags.listid) a['list-id']=tags.listid; if(tags.heading) a.heading=tags.heading; }
  if (type === 'heading' && (tags.archived || tags.done)) { delete a.completed; a.archived=true; }
  return a;
}
for (const raw of source.split('\n')) {
  if (error) break;
  if (!raw.trim()) continue;
  const prefix = raw.match(/^[ \t]*/)[0];
  const depth = prefix.replace(/\t/g, '    ').length;
  const line = raw.slice(prefix.length);
  while (stack.length && stack[stack.length - 1].depth >= depth) stack.pop();
  const parent = stack.length ? stack[stack.length - 1] : null;
  if (line.startsWith('- ')) {
    const parsed = parseTags(line.slice(2));
    if (!parsed.title || parsed.title.length > 4000) { fail('A task needs a valid title.'); break; }
    if (parent && parent.type === 'to-do') {
      const keys=Object.keys(parsed.tags);
      if (keys.some(k => !['done','completed','canceled','cancelled'].includes(k))) { fail('Checklist items only support completion tags.'); break; }
      const attr={title:parsed.title};
      if(parsed.tags.done || parsed.tags.completed) attr.completed=true;
      if(parsed.tags.canceled || parsed.tags.cancelled) attr.canceled=true;
      if(!parent.object.attributes['checklist-items']) parent.object.attributes['checklist-items']=[];
      if(parent.object.attributes['checklist-items'].length>=100){fail('A task can have at most 100 checklist items.');break;}
      parent.object.attributes['checklist-items'].push({type:'checklist-item',attributes:attr});
      stack.push({depth,type:'checklist-item',object:null});
    } else {
      const attr={title:parsed.title,...metadata(parsed.tags,'to-do')};
      const object={type:'to-do',attributes:attr};
      if(parent && parent.project) parent.project.attributes.items.push(object);
      else if(!parent) items.push(object);
      else { fail('Tasks must be inside a project, heading, or task.'); break; }
      stack.push({depth,type:'to-do',object,project:parent && parent.project});
    }
  } else {
    const parsed = parseTags(line); const isProject = parsed.title.endsWith(':');
    if (isProject) {
      const title=parsed.title.slice(0,-1).trim(); if(!title){fail('A project needs a title.');break;}
      if (!parent) {
        const object={type:'project',attributes:{title,items:[],...metadata(parsed.tags,'project')}};
        items.push(object); stack.push({depth,type:'project',object,project:object});
      } else if(parent.type==='project') {
        const object={type:'heading',attributes:{title,...metadata(parsed.tags,'heading')}};
        parent.project.attributes.items.push(object); stack.push({depth,type:'heading',object,project:parent.project});
      } else { fail('Unsupported nested project.'); break; }
    } else {
      if (!parent || !['project','to-do'].includes(parent.type) || Object.keys(parsed.tags).length) { fail('A note must be inside a task or project and cannot contain tags.'); break; }
      const a=parent.object.attributes; a.notes=a.notes ? a.notes+'\n'+line.trim() : line.trim();
      if(a.notes.length>10000){fail('Notes exceed the Things limit.');break;}
    }
  }
  if(error) break;
}
if (promptCancelled) context.cancel();
else if (error) context.fail(error);
else if (!items.length) context.fail('Add at least one task or project.');
else if (!app.openURL('things:///json?reveal=true&data=' + encodeURIComponent(JSON.stringify(items)))) context.fail('Could not open Things.');
